def image(path,label):
 im=Image.open(B/path);w,h=im.size
 return f'<figure><figcaption>{E(label)} · {w}×{h}</figcaption><img src="{E(path)}" width="{w}" height="{h}" alt="{E(label)}"></figure>'
def pair(a,b,labela,labelb):return '<div class="scroll"><div class="pair">'+image(a,labela)+image(b,labelb)+'</div></div>'
